import { wpGraphQL } from '../../../../lib/wp';

import styles from "../../page.module.css";

import Link from "next/link";

//Navbar
import BaddNavbar from "../../../components/BaddNavbar";

//Footer
import BaddFooter from "../../../components/BaddFooter";

type SlugsData = {
  posts: {
    nodes: {
      slug: string
    }[]
  }
};

type PostData = {
  post: {
    title: string
    content: string
    date: string
  }
};

const GET_POST_SLUGS = `
  query GetPostSlugs {
    posts(first: 100) {
      nodes {
        slug
      }
    }
  }
`;

const GET_POST = `
  query GetPost($slug: ID!) {
    post(id: $slug, idType: SLUG) {
      title
      content
      date
    }
  }
`;

export async function generateStaticParams() {
  const data = await wpGraphQL<SlugsData>(GET_POST_SLUGS)

  return data.posts.nodes.map((post) => ({
    slug: post.slug,
  }))
}


export default async function PostPage({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params

  const data = await wpGraphQL<PostData>(GET_POST, { slug })

  return (
    <main>
      <h1>{data.post.title}</h1>

      <div
        dangerouslySetInnerHTML={{
          __html: data.post.content,
        }}
      />
    </main>
  )
}
